# Cuentos de Estudios Sociales de 6.º (5 a 8)
from personajes6 import *

CUENTOS = [
dict(area="sociales", n=5, slug="twelve-tables", std="SS.6-8.CV.2.LC",
  std_texto="explain the origins and purposes of written laws and governing documents, from the Twelve Tables of Rome to classroom rules.",
  titulo="Rules on the wall", titulo_es="Reglas en la pared",
  entrada="A story about classroom rules and the Twelve Tables, the first written laws of Rome.",
  entrada_es="Un cuento sobre las reglas del salón y las Doce Tablas, las primeras leyes escritas de Roma.",
  tema="Written laws help people know their rights and limit power", tema_es="Las leyes escritas ayudan a conocer los derechos y a limitar el poder",
  descripcion="A Grade 6 social studies story: a class argument about rules leads students to the Twelve Tables of ancient Rome and the purpose of written laws. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In the classroom, Selena and Israel tape a large poster of class rules on the wall while Ms. Haddad holds up a picture of twelve bronze tablets and Sophia writes in a notebook.",
  escena=f"A sixth grade classroom in Chicago: {SELENA}, and {ISRAEL}, tape a big poster to the wall, the poster has only small drawings of hands raised, a clock and two friends shaking hands, with no words; only one teacher, {P_HADDAD}, holds up a picture of twelve shiny bronze tablets standing in an ancient Roman square with columns; {SOPHIA}, writes in a notebook at her desk",
  palabras=[
    ("law","law","A rule that everyone in a community must follow, made by the government.","ley","Una regla que todos en una comunidad deben seguir, hecha por el gobierno."),
    ("republic","republic","A government in which citizens choose leaders to make decisions for them, instead of a king.","república","Un gobierno en el que los ciudadanos eligen líderes que deciden por ellos, en lugar de un rey."),
    ("patricians","patricians","In ancient Rome, the rich and powerful families who held most of the power.","patricios","En la antigua Roma, las familias ricas y poderosas que tenían casi todo el poder."),
    ("plebeians","plebeians","In ancient Rome, the ordinary citizens, like farmers, shopkeepers and workers.","plebeyos","En la antigua Roma, los ciudadanos comunes, como campesinos, comerciantes y trabajadores."),
    ("code","code of laws","A written list of a community's laws, organized so that people can read them.","código de leyes","Una lista escrita de las leyes de una comunidad, organizada para que la gente pueda leerla."),
    ("rights","rights","Freedoms and protections that belong to people, which others must respect.","derechos","Libertades y protecciones que tienen las personas y que los demás deben respetar.")],
  parrafos=[
    '''"That's not fair!" shouted Israel. Selena had taken the last basketball at recess, and Israel said the rule was that sixth graders took turns. "What rule?" said Selena. "I never heard of that rule." Ms. Haddad looked at both of them. "Where is that rule written?" Nobody knew.''',
    '''"You two just found a problem the Romans had about 2,500 years ago," said Ms. Haddad. "Rome had become a [[republic|republic]]. Instead of a king, citizens chose leaders. But Romans were divided into two groups." {{a|"The [[patricians|patricians]] were rich, old families who held most of the power. The [[plebeians|plebeians]] were ordinary people: farmers, bakers and workers."}}''',
    '''"Back then, the laws weren't written down for everyone to see," she went on. {{b|"Patrician judges kept the laws in their heads. When a plebeian went to court, the judge could say the law was whatever he wanted it to be. Plebeians couldn't check."}} Israel nodded. "Like Selena's rule." "Like my rule?" said Selena. "Like your rule," said Israel.''',
    '''"The plebeians got angry," said Ms. Haddad. "They refused to work and even walked out of the city. Finally, around 450 BCE, the Romans wrote their laws on twelve bronze tablets." {{c|"They called them the Twelve Tables, and they set them up in the Forum, the main square, so that anyone who could read could see the [[law|law]], or ask someone to read it to them."}}''',
    '''Sophia raised her hand. "What did the laws say?" "Lots of everyday things," said Ms. Haddad. "What happened if your neighbor's tree hung over your land, how to pay back a debt, and how a trial worked. {{d|They also said how a person could be called to court, and that a trial had to follow the same steps for everyone. The Twelve Tables were Rome's first written [[code|code of laws]].}}"''',
    '''"Were the laws fair?" asked Selena. "Some of them seem very harsh to us today," said Ms. Haddad. {{e|"But writing them down was a big step. When laws are written, everyone can know their [[rights|rights]], and powerful people can't change the rules whenever they want."}}''',
    '''"Does the United States have something like that?" asked Israel. Ms. Haddad pointed to the poster of the Constitution in the corner. "Our Constitution is written down too. It says how the government works, what its limits are, and what rights the people have. Romans called their tablets the source of all law. Many Americans feel that way about the Constitution."''',
    '''That afternoon, the class wrote its own rules on a poster: take turns with the basketball, listen when someone speaks, and help a classmate who is stuck. Everyone signed it. Selena signed first. Then she handed Israel the basketball. "Your turn," she said. "It's written."'''],
  preguntas=[
    ("a","Who were the patricians and the plebeians?","¿Quiénes eran los patricios y los plebeyos?",
     ["Kings and soldiers who fought for Rome","Powerful families and ordinary people","Teachers and students in Roman schools"],1,
     "The patricians were rich, old families with most of the power, and the plebeians were ordinary people."),
    ("b","What was the problem with laws that were not written down?","¿Cuál era el problema con las leyes que no estaban escritas?",
     ["Judges could say the law was whatever they wanted","Plebeians forgot the laws because there were too many","The laws were written in a language nobody spoke"],0,
     "Patrician judges kept the laws in their heads, so they could say the law was whatever they wanted, and plebeians couldn't check."),
    ("c","Why did the Romans put the Twelve Tables in the Forum?","¿Por qué los romanos pusieron las Doce Tablas en el Foro?",
     ["So the bronze would shine in the sun","So soldiers could guard them at night","So anyone could see and know the laws"],2,
     "They set up the tablets in the main square so that anyone could see the law or ask someone to read it."),
    ("d","What did the Twelve Tables say about trials?","¿Qué decían las Doce Tablas sobre los juicios?",
     ["Only patricians could go to court","Trials followed the same steps for everyone","The king decided every trial himself"],1,
     "The Twelve Tables said how a person could be called to court, and that a trial had to follow the same steps for everyone."),
    ("e","Why was writing the laws down a big step?","¿Por qué escribir las leyes fue un gran paso?",
     ["Plebeians no longer had to follow laws","The laws became much kinder right away","Everyone could know the rules and their rights"],2,
     "When laws are written, everyone can know their rights, and powerful people can't change the rules whenever they want.")],
  reto=dict(tipo="Explain the purpose", tipo_es="Explica el propósito",
    pregunta="Explain two purposes of a written code of laws, using the Twelve Tables as an example. Then explain how your class poster has the same purposes.",
    pregunta_es="Explica dos propósitos de un código de leyes escrito, usando como ejemplo las Doce Tablas. Después explica cómo el cartel de la clase tiene los mismos propósitos.",
    pista="Purpose 1: so everyone can know the rules and their rights, like plebeians reading the tablets in the Forum. Purpose 2: so powerful people can't change the rules whenever they want, like patrician judges did. The class poster does the same: everyone can see the basketball rule, and nobody can say \"I never heard of that rule.\""),
  mdc=dict(pregunta="Some laws of the Twelve Tables seem harsh to us today. Can a law be written down and still be unfair? Explain, and say what people can do when a written law is unfair.",
    pregunta_es="Algunas leyes de las Doce Tablas nos parecen duras hoy. ¿Puede una ley estar escrita y aun así ser injusta? Explica y di qué puede hacer la gente cuando una ley escrita es injusta.",
    pista="Yes: writing a law makes it public, but it does not make it fair. For example, one of the Twelve Tables did not allow patricians and plebeians to marry each other. In a republic, people can work to change unfair laws by speaking up, voting, protesting peacefully and electing new leaders. The plebeians themselves kept pushing for more rights after the Twelve Tables. The United States Constitution also has a way to change it: amendments."),
  pausa=dict(emoji="🖼️", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at the Pont du Gard, a Roman aqueduct bridge in what is now southern France. The Romans built it about 2,000 years ago to carry water to the city of Nîmes.",
    intro_es="Observa el Pont du Gard, un puente acueducto romano en lo que hoy es el sur de Francia. Los romanos lo construyeron hace unos 2,000 años para llevar agua a la ciudad de Nimes.",
    enlace=("https://whc.unesco.org/en/list/344","See the Pont du Gard (UNESCO World Heritage)"),
    describe="A huge stone bridge crosses a river valley. It has three levels of arches, one on top of the other: big arches at the bottom and many small arches at the top. The water flowed in a channel at the very top, almost 50 meters above the river.",
    describe_es="Un enorme puente de piedra cruza el valle de un río. Tiene tres pisos de arcos, uno encima del otro: arcos grandes abajo y muchos arcos pequeños arriba. El agua corría por un canal en la parte más alta, a casi 50 metros sobre el río.",
    preguntas=[("Why do you think the builders used arches instead of a solid wall?","¿Por qué crees que los constructores usaron arcos en lugar de un muro macizo?"),
               ("A government had to plan and pay for this bridge. What does it tell you about the Roman government and what it wanted people to think?","Un gobierno tuvo que planear y pagar este puente. ¿Qué te dice sobre el gobierno romano y lo que quería que la gente pensara?")],
    pista="Arches are strong: they push the weight down and out into the pillars, so the bridge can be tall while using less stone, and the river can flow through. A project this big needed planning, money, laws and many workers, so it shows that Rome had a strong, organized government. It is also beautiful, which told people that Rome was powerful and took care of its cities.")),

dict(area="sociales", n=6, slug="silk-road", std="SS.6-8.G.8",
  std_texto="explain how transportation and communication along trade routes like the Silk Road spread goods, ideas and inventions.",
  titulo="Pass it down the Silk Road", titulo_es="Pásalo por la Ruta de la Seda",
  entrada="A story about a classroom trading game and the Silk Road, where goods and ideas traveled.",
  entrada_es="Un cuento sobre un juego de intercambio en clase y la Ruta de la Seda, por donde viajaban productos e ideas.",
  tema="Trade routes carried goods, ideas and inventions far away", tema_es="Las rutas comerciales llevaron productos, ideas e inventos muy lejos",
  descripcion="A Grade 6 social studies story: a classroom trading game shows how the Silk Road carried goods, ideas and inventions between Asia, Africa and Europe. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In the classroom, rows of desks are set up as trading cities; Sophia passes a silk scarf to Elías while Salma whispers a message to Athena and Ms. Haddad points at a long route on a map.",
  escena=f"A sixth grade classroom in Chicago arranged as a long line of desks, each desk with a small paper sign showing only a drawing of a camel, a tent or a boat; {SOPHIA}, hands a shiny red silk scarf to {ELIAS}; {SALMA}, whispers into the ear of {ATHENA}, who giggles; {P_HADDAD}, points at a large map of Asia and Europe with a long dotted line crossing deserts and mountains from China to the Mediterranean Sea, with no words on the map",
  palabras=[
    ("route","trade route","A path that merchants follow over and over to carry goods to sell.","ruta comercial","Un camino que los comerciantes recorren una y otra vez para llevar productos que venden."),
    ("merchant","merchant","A person who buys and sells goods to make money.","comerciante (mercader)","Una persona que compra y vende productos para ganar dinero."),
    ("caravan","caravan","A group of travelers and animals, like camels, that cross a long distance together.","caravana","Un grupo de viajeros y animales, como camellos, que recorren juntos una gran distancia."),
    ("oasis","oasis","A place in the desert with water, where plants can grow and travelers can rest.","oasis","Un lugar en el desierto con agua, donde crecen plantas y los viajeros pueden descansar."),
    ("goods","goods","Things that people make or grow to sell or trade, like silk, spices or glass.","productos (mercancías)","Cosas que la gente hace o cultiva para vender o intercambiar, como seda, especias o vidrio."),
    ("diffusion","cultural diffusion","When ideas, beliefs, foods or inventions spread from one group of people to another.","difusión cultural","Cuando ideas, creencias, comidas o inventos pasan de un grupo de personas a otro.")],
  parrafos=[
    '''When the class walked in, the desks were lined up in one long snake across the room. Each desk had a paper sign: Chang'an, Dunhuang, Samarkand, Baghdad, Antioch. "Today, each desk is a city on the Silk Road," said Ms. Haddad. "And you are [[merchant|merchants]]."''',
    '''{{a|"The Silk Road wasn't one road," she explained. "It was a network of [[route|trade routes]], thousands of miles long, that connected China with Central Asia, India, the Middle East, Africa and Europe."}} Merchants used these routes for more than 1,500 years, starting about 2,100 years ago, she said, and few merchants ever traveled the whole thing.''',
    '''She gave Sophia, at the Chang'an desk, a red silk scarf. "In China, people knew how to make silk from silkworms, and people far away wanted it badly. Pass it west, and each merchant can sell it for a little more." The scarf traveled from desk to desk. By the time it reached Antioch, Ms. Haddad had written its price on the board five times, each one higher.''',
    '''"Why didn't one person just carry it the whole way?" asked Elías. "Because the trip was brutal," said Ms. Haddad. "Deserts, high mountains, bandits." {{b|"Merchants traveled in [[caravan|caravans]] of camels, which can walk for days with little water. They stopped at each [[oasis|oasis]], where they could drink, rest and trade."}}''',
    '''Then Ms. Haddad gave Athena, at the Antioch desk, a jar of glass beads, and Salma, at Baghdad, a small bag of cinnamon. "[[goods|Goods]] went in both directions," she said. "Silk and paper moved west. Glass, wool, horses and silver moved east. Spices came from India and Southeast Asia."''',
    '''"Now here's the real treasure," she said, and she whispered a sentence into Sophia's ear. Sophia whispered it to Elías, Elías to Salma, Salma to Athena. Athena laughed. "Camels love to dance in the moonlight?" Ms. Haddad laughed too. "I said, Camels can carry a lot in the moonlight." {{c|"Ideas traveled on the Silk Road too, and they changed as they moved from person to person, just like your message."}}''',
    '''"Which ideas?" asked Salma. {{d|"Buddhism traveled from India to China along these routes. Papermaking traveled from China to the Middle East and then to Europe. Foods, music and art traveled too. When ideas and inventions spread from one people to another, we call it [[diffusion|cultural diffusion]]."}} "Did anything bad travel?" asked Elías. "Yes. Diseases also traveled with the caravans."''',
    '''At the end of class, Ms. Haddad asked everyone to look at their own things. Sophia's pencil, Salma's paper, Elías's rice for lunch. {{e|"Today our Silk Road is made of ships, planes and the internet," she said. "A video can cross the world in one second, and ideas still change along the way."}} Athena grinned. "Like dancing camels."'''],
  preguntas=[
    ("a","What was the Silk Road?","¿Qué era la Ruta de la Seda?",
     ["One straight road from China to Rome","A network of trade routes across continents","A river that carried silk boats to Europe"],1,
     "The Silk Road was a network of trade routes, thousands of miles long, that connected China with many other lands."),
    ("b","Why did merchants use camels and stop at oases?","¿Por qué los comerciantes usaban camellos y paraban en los oasis?",
     ["Camels need little water, and oases had water and rest","Camels were faster than any horse or boat at the time","Oases were the only places where they could buy silk"],0,
     "Camels can walk for days with little water, and at each oasis merchants could drink, rest and trade."),
    ("c","What did the whispering game show about ideas?","¿Qué mostró el juego de los susurros sobre las ideas?",
     ["Ideas never travel as far as goods","Merchants always kept ideas a secret","Ideas can change as they pass along"],2,
     "Ideas traveled on the Silk Road and changed as they moved from person to person, just like the message."),
    ("d","Which is an example of cultural diffusion from the story?","¿Cuál es un ejemplo de difusión cultural del cuento?",
     ["The price of silk going up and up","Merchants resting at an oasis","Buddhism traveling from India to China"],2,
     "Buddhism spread from India to China along the trade routes, which is cultural diffusion."),
    ("e","What is our Silk Road today, according to Ms. Haddad?","Según la maestra Haddad, ¿cuál es nuestra Ruta de la Seda hoy?",
     ["Long lines of camels and horses","Ships, planes and the internet","Only the roads inside the United States"],1,
     "Today goods and ideas travel by ships, planes and the internet, and ideas still change along the way.")],
  reto=dict(tipo="Trace the spread", tipo_es="Sigue el recorrido",
    pregunta="Choose one good and one idea from the story. For each one, explain where it started, where it traveled and how transportation helped it spread.",
    pregunta_es="Elige un producto y una idea del cuento. Para cada uno, explica dónde empezó, a dónde viajó y cómo el transporte ayudó a que se difundiera.",
    pista="Good: silk started in China and traveled west, carried by camel caravans that stopped at oases, and its price went up at each city. Idea: Buddhism started in India and traveled to China with merchants and travelers on the trade routes. Without caravans and safe stops, neither could have traveled so far."),
  mdc=dict(pregunta="The internet spreads ideas much faster than the Silk Road did. Give one benefit and one problem of ideas spreading so fast, and explain how people can check whether an idea changed along the way.",
    pregunta_es="Internet difunde las ideas mucho más rápido que la Ruta de la Seda. Da un beneficio y un problema de que las ideas se difundan tan rápido, y explica cómo puede la gente comprobar si una idea cambió en el camino.",
    pista="Benefit: people can learn about inventions, medicine or other cultures right away. Problem: false or changed information can also spread to millions of people before anyone checks it. To check, people can look for the original source, compare several reliable sources and ask who made the message and why, just as historians do."),
  pausa=dict(emoji="🐫", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at this clay camel, made in China during the Tang dynasty, about 1,300 years ago. Figures like this were placed in tombs.",
    intro_es="Observa este camello de barro, hecho en China durante la dinastía Tang, hace unos 1,300 años. Figuras como esta se colocaban en las tumbas.",
    enlace=("https://www.metmuseum.org/art/collection/search/49368","See the camel (The Metropolitan Museum of Art)"),
    describe="A camel stands tall, ready for a long trip. Its body is covered in a shiny glaze of several colors, often amber, green and cream. This style is called sancai, which means three colors.",
    describe_es="Un camello está de pie, muy erguido, listo para un largo viaje. Su cuerpo está cubierto de un esmalte brillante de varios colores, a menudo ámbar, verde y crema. Este estilo se llama sancai, que significa «tres colores».",
    preguntas=[("Why do you think a family in China wanted a camel in a tomb?","¿Por qué crees que una familia en China quería un camello en una tumba?"),
               ("What does this camel tell you about how important the Silk Road was in Tang China?","¿Qué te dice este camello sobre lo importante que era la Ruta de la Seda en la China Tang?")],
    pista="Camels carried the goods that made merchants rich, so a camel was a sign of wealth and trade. Families placed figures like this in tombs to show who the person was and what was important in their life. If artists made many beautiful camels, trade on the Silk Road must have been a big part of life in Tang China.")),

dict(area="sociales", n=7, slug="printing", std="SS.6-8.EC.4",
  std_texto="explain how innovation and entrepreneurship, like the invention of paper and printing, change how people work and live.",
  titulo="The card company", titulo_es="La compañía de tarjetas",
  entrada="A story about a class business and the inventions of paper and printing in China.",
  entrada_es="Un cuento sobre un negocio de la clase y la invención del papel y la imprenta en China.",
  tema="Innovations like paper and printing changed how people work", tema_es="Innovaciones como el papel y la imprenta cambiaron el trabajo de la gente",
  descripcion="A Grade 6 social studies story: a class card business discovers why paper and printing were such important innovations. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="At a long table, Daniel tiredly draws cards one by one while Salma and Sophia stamp the same picture again and again with a carved block and ink; Ms. Haddad smiles and holds a finished card.",
  escena=f"A busy art room in Chicago: on a long table, stacks of blank cards and a small tray of red ink; {DANIEL}, looks tired, drawing a flower picture on a card by hand with a marker; {SALMA}, and {SOPHIA}, happily press a carved wooden block into red ink and stamp the same flower picture onto many cards in a row; {P_HADDAD}, smiles and holds up a finished card with a flower picture",
  palabras=[
    ("innovation","innovation","A new idea, tool or way of doing things that makes something work better.","innovación","Una idea, herramienta o forma de hacer las cosas que es nueva y hace que algo funcione mejor."),
    ("entrepreneur","entrepreneur","A person who starts a business and takes a risk to make or sell something new.","emprendedor o emprendedora","Una persona que empieza un negocio y se arriesga para hacer o vender algo nuevo."),
    ("productivity","productivity","How much work or how many products people can make in a certain amount of time.","productividad","Cuánto trabajo o cuántos productos puede hacer la gente en cierto tiempo."),
    ("woodblock","woodblock printing","Printing by carving a whole page into a block of wood, inking it and pressing paper on it.","impresión con bloques de madera (xilografía)","Imprimir tallando una página completa en un bloque de madera, poniéndole tinta y presionando papel encima."),
    ("movable","movable type","Small separate pieces, each with one character, that can be arranged into any page and used again.","tipos móviles","Piezas pequeñas y separadas, cada una con un carácter, que se pueden ordenar para formar cualquier página y volver a usar."),
    ("cost","cost","The money, time or materials you need to make something.","costo","El dinero, el tiempo o los materiales que se necesitan para hacer algo.")],
  parrafos=[
    '''The sixth grade decided to raise money for a field trip by selling greeting cards at the winter fair. "I'll be the boss," said Daniel. "Every card will be a masterpiece." He drew the first card by hand: a flower, very carefully. It took him twenty minutes. "We need 200 cards," said Salma. Daniel looked at the clock and groaned.''',
    '''"You need an [[innovation|innovation]]," said Ms. Haddad. "A better way of doing the work." She told them about China, long ago. {{a|"Around the year 105, an official named Cai Lun improved a way of making paper from tree bark, old rags and fishing nets. Before that, people wrote on bamboo strips, which were heavy, or on silk, which was very expensive."}}''',
    '''"Paper was cheap and light," she said. "More people could write letters, keep records and read books." Then she held up a block of wood with a flower carved into it, backward. {{b|"Next, Chinese printers invented [[woodblock|woodblock printing]]. They carved a whole page into a wooden block, covered it with ink and pressed paper on top. One block could print hundreds of copies."}}''',
    '''Salma and Sophia tried it. Press, stamp, lift. Press, stamp, lift. In twenty minutes, they made forty cards, while Daniel finished his second masterpiece. {{c|"That's [[productivity|productivity]]," said Ms. Haddad. "The same number of people, in the same time, making many more products."}}''',
    '''"There's a problem," said Sophia. "What if we want to print a different message on each card? We'd have to carve a new block every time." Ms. Haddad smiled. {{d|"A man named Bi Sheng had the same thought around the year 1040. He made [[movable|movable type]]: little clay pieces, each with one character. Printers could arrange them into any page, print it, then take them apart and use them again."}} About 400 years later, Johannes Gutenberg built a printing press with metal movable type in Germany, and books spread across Europe.''',
    '''Daniel crossed his arms. "But my hand-drawn cards are better." "Maybe some people will pay more for them," said Ms. Haddad. "That's a real business choice." {{e|"An [[entrepreneur|entrepreneur]] decides what to make, how to make it and what to charge. Printing lowers the [[cost|cost]] of each card, so you can sell more cards for less money. Special hand-drawn cards can sell for more."}}''',
    '''So the class made a plan: 190 printed cards at one dollar each, and ten of Daniel's hand-drawn cards at three dollars each, signed by the artist. At the winter fair, the printed cards sold out by noon. Daniel's cards sold out too, but it took the whole day.''',
    '''They earned 220 dollars, enough for the field trip. On the way home, Daniel said, "Cai Lun and Bi Sheng should get a thank-you card." "From your company?" asked Salma. "Printed," said Daniel. "Not hand-drawn. I'm tired."'''],
  preguntas=[
    ("a","Why was Cai Lun's paper an important improvement?","¿Por qué el papel de Cai Lun fue una mejora importante?",
     ["Bamboo was heavy and silk was expensive","Paper was stronger than wood or stone","Nobody in China knew how to write yet"],0,
     "Before paper, people wrote on heavy bamboo strips or expensive silk; paper was cheap and light."),
    ("b","How did woodblock printing work?","¿Cómo funcionaba la impresión con bloques de madera?",
     ["A machine wrote each letter with a pen","A whole page was carved, inked and pressed","Each copy was painted by a different artist"],1,
     "Printers carved a whole page into a wooden block, covered it with ink and pressed paper on top."),
    ("c","How did the stamp show productivity?","¿Cómo mostró la productividad el sello?",
     ["The cards became more beautiful than before","Daniel worked faster with his favorite marker","The same people made more cards in the same time"],2,
     "In twenty minutes, Salma and Sophia made forty cards: the same people, in the same time, made many more products."),
    ("d","What problem did movable type solve?","¿Qué problema resolvió la imprenta de tipos móviles?",
     ["Paper was too expensive to buy","A new block had to be carved for each page","Ink dried too fast on the wooden blocks"],1,
     "With movable type, printers could arrange small pieces into any page and use them again instead of carving a new block."),
    ("e","Why could printed cards sell for less money?","¿Por qué las tarjetas impresas se podían vender más baratas?",
     ["The printed cards were smaller than the others","People don't like printed cards very much","Printing lowered the cost of each card"],2,
     "Printing lowers the cost of each card, so the class could sell more cards for less money.")],
  reto=dict(tipo="Explain the effects", tipo_es="Explica los efectos",
    pregunta="Explain how one innovation from the story, paper or printing, changed people's lives. Give one effect on work and one effect on learning.",
    pregunta_es="Explica cómo una innovación del cuento, el papel o la imprenta, cambió la vida de la gente. Da un efecto en el trabajo y un efecto en el aprendizaje.",
    pista="Printing: on work, printers could make hundreds of copies with less time and less cost, so books became cheaper. On learning, more people could buy books and learn to read, so ideas spread faster. Paper: it was cheap and light, so more people could keep records and write letters."),
  mdc=dict(pregunta="Think of an innovation from your lifetime, like video calls or online maps. Who were the winners and who were the losers when it arrived? Explain how entrepreneurs had to adapt.",
    pregunta_es="Piensa en una innovación de tu vida, como las videollamadas o los mapas en línea. ¿Quiénes ganaron y quiénes perdieron cuando llegó? Explica cómo tuvieron que adaptarse los emprendedores.",
    pista="Example: online maps. Winners: drivers who save time, and companies that make apps and phones. Losers: companies that printed paper maps sold fewer of them. Some of them adapted by making digital maps or selling special maps for hikers. Every innovation creates new jobs and changes old ones, just as printing changed the work of people who copied books by hand."),
  pausa=dict(emoji="📜", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at the Diamond Sutra, a Buddhist book printed in China in the year 868 with woodblocks. It is the oldest printed book we know of that has an exact date.",
    intro_es="Observa el Sutra del Diamante, un libro budista impreso en China en el año 868 con bloques de madera. Es el libro impreso más antiguo que conocemos con una fecha exacta.",
    enlace=("https://www.cabinet.ox.ac.uk/worlds-earliest-dated-printed-book-diamond-sutra-868-ce","Learn about the Diamond Sutra (University of Oxford)"),
    describe="The book is a long scroll, more than five meters long. At the start is a printed picture: the Buddha sits in the center under a decorated canopy, teaching an old follower who kneels in front of him, surrounded by many other figures.",
    describe_es="El libro es un rollo largo, de más de cinco metros. Al principio hay un dibujo impreso: el Buda está sentado en el centro bajo un dosel decorado y enseña a un seguidor anciano que está arrodillado frente a él, rodeado de muchas otras figuras.",
    preguntas=[("Every line of the picture had to be carved backward in wood. What does that tell you about the skill of the printers?","Cada línea del dibujo tuvo que tallarse al revés en la madera. ¿Qué te dice eso sobre la habilidad de los impresores?"),
               ("Why do you think people wanted to print a religious book many times instead of copying it by hand?","¿Por qué crees que la gente quería imprimir muchas veces un libro religioso en lugar de copiarlo a mano?")],
    pista="Carving a detailed picture backward, so it prints the right way, takes great skill and patience. The carvers were artists as well as workers. Printing let people make many copies quickly, so more people could have and share the book. Religious and important books were among the first things people printed, in China and later in Europe.")),

dict(area="sociales", n=8, slug="mali", std="SS.6-8.G.12",
  std_texto="explain how the physical environment and resources affected production and trade in the Mali Empire and the world trade network.",
  titulo="Worth its weight in salt", titulo_es="Vale su peso en sal",
  entrada="A story about the Mali Empire, the trade of gold and salt, and Mansa Musa.",
  entrada_es="Un cuento sobre el Imperio de Malí, el comercio de oro y sal, y Mansa Musa.",
  tema="Mali grew rich by trading gold for salt across the Sahara", tema_es="Malí se enriqueció intercambiando oro por sal a través del Sahara",
  descripcion="A Grade 6 social studies story: students learn how the gold and salt trade made the Mali Empire rich and famous. With key words, glossary, questions, an art connection and optional help in Spanish.",
  alt="In the classroom, Elías holds a jar of salt and Selena holds a gold-painted rock as they pretend to bargain, while Ms. Haddad shows a map of West Africa and the Sahara.",
  escena=f"A sixth grade classroom in Chicago: {ELIAS}, holds up a small glass jar full of white salt; {SELENA}, holds up a rock painted shiny gold, and the two pretend to bargain, smiling; {P_HADDAD}, stands next to a large map of West Africa with a big yellow desert in the north, green land in the south and a blue river curving between them, with no words on the map",
  palabras=[
    ("resource","natural resource","Something from nature that people use, like water, gold, salt or wood.","recurso natural","Algo de la naturaleza que la gente usa, como agua, oro, sal o madera."),
    ("scarce","scarce","When there is not enough of something for everyone who wants it.","escaso","Cuando no hay suficiente de algo para todos los que lo quieren."),
    ("empire","empire","A large area of many lands and peoples ruled by one government or ruler.","imperio","Una gran zona de muchas tierras y pueblos gobernada por un solo gobierno o gobernante."),
    ("export","export","A product that a place sells to other places.","exportación","Un producto que un lugar vende a otros lugares."),
    ("import","import","A product that a place buys from other places.","importación","Un producto que un lugar compra a otros lugares."),
    ("pilgrimage","pilgrimage","A long journey to a holy place for religious reasons.","peregrinación","Un viaje largo a un lugar sagrado por motivos religiosos.")],
  parrafos=[
    '''Ms. Haddad put two things on her desk: a jar of salt and a rock painted gold. "Which one would you trade your lunch for?" she asked. "The gold, obviously," said Selena. Elías wasn't so sure. "Depends on how hungry I am."''',
    '''"Seven hundred years ago, in West Africa, people would trade gold for salt," said Ms. Haddad. She pointed to a map. In the north was the Sahara, a huge desert. In the south were green lands along the Niger River. {{a|"Deep in the Sahara, there were mines full of salt, but almost nothing grew there. In the south, there was gold in the ground, but very little salt."}}''',
    '''"Why did they need salt so much?" asked Selena. {{b|"In the hot, wet south, people and animals lose salt when they sweat, and they need it to stay healthy," said Ms. Haddad. "Salt also kept meat and fish from spoiling. In the south, salt was [[scarce|scarce]], so people valued it very highly."}}''',
    '''Each place had a [[resource|natural resource]] the other needed. {{c|"So merchants crossed the Sahara with caravans of camels, carrying huge slabs of salt south and gold north. Gold was one of the main [[export|exports]] of the lands in the south, and salt was one of its main [[import|imports]]."}} The gold then traveled on to North Africa and Europe, where it was turned into coins.''',
    '''Right in the middle of these trade routes grew the [[empire|empire]] of Mali. "Mali's rulers didn't need to dig the gold themselves," said Ms. Haddad. {{d|"They controlled the routes and the trading cities, like Timbuktu, and they collected taxes on the goods that passed through. That made Mali one of the richest empires in the world."}}''',
    '''"Its most famous ruler was Mansa Musa," she continued. "Mansa means king. In 1324, he made a [[pilgrimage|pilgrimage]] to Mecca, the holy city of Islam, with thousands of people and many camels carrying gold." {{e|"When he passed through Cairo, in Egypt, he gave away and spent so much gold that, for years, gold there was worth less than before."}}''',
    '''"He gave away so much gold that gold got cheaper?" said Elías. "That's like when everybody has the same trading card, and nobody wants it anymore." "Exactly," said Ms. Haddad. "And people in Europe and the Middle East started talking about Mali. Mansa Musa also brought scholars and builders back home, and Timbuktu became famous for its mosques and libraries."''',
    '''At the end of class, Elías picked up the jar of salt. "I'd still trade the gold for the salt," he said. "Why?" asked Selena. "Because if I lived in the south seven hundred years ago, I would be sweaty, and my fish would be spoiled." Ms. Haddad laughed. "Spoken like a true merchant."'''],
  preguntas=[
    ("a","Why did people in the north and the south need to trade?","¿Por qué la gente del norte y la del sur necesitaba comerciar?",
     ["Each had a resource the other lacked","Both places had too much gold","Their kings ordered them to be friends"],0,
     "The Sahara had salt but almost nothing grew there, and the south had gold but very little salt."),
    ("b","Why was salt so valuable in the south?","¿Por qué la sal era tan valiosa en el sur?",
     ["It was used to make gold coins shine","People needed it, and it was scarce there","It was the only food that grew in the south"],1,
     "People and animals needed salt to stay healthy and to keep food from spoiling, and salt was scarce in the south."),
    ("c","What did merchants carry across the Sahara?","¿Qué llevaban los comerciantes a través del Sahara?",
     ["Silk and spices to the river towns","Water and wood to the salt mines","Salt to the south and gold to the north"],2,
     "Caravans carried salt south and gold north; gold was an export, and salt was an import."),
    ("d","How did Mali become so rich?","¿Cómo se volvió tan rico Malí?",
     ["It sold camels to every country in Europe","Its people dug all the salt out of the desert","It controlled trade routes and collected taxes"],2,
     "Mali's rulers controlled the routes and trading cities and collected taxes on the goods that passed through."),
    ("e","What happened to gold in Cairo after Mansa Musa visited?","¿Qué pasó con el oro en El Cairo después de la visita de Mansa Musa?",
     ["Gold became too rare for people to buy","Gold was worth less for years","Gold was no longer used in Egypt"],1,
     "Mansa Musa gave away and spent so much gold that, for years, gold in Cairo was worth less than before.")],
  reto=dict(tipo="Connect environment and trade", tipo_es="Conecta el ambiente y el comercio",
    pregunta="Explain how the environment of the Sahara and of the lands in the south led to the gold and salt trade. Use the words resource, scarce, export and import.",
    pregunta_es="Explica cómo el ambiente del Sahara y el de las tierras del sur llevaron al comercio de oro y sal. Usa las palabras recurso, escaso, exportación e importación.",
    pista="The Sahara had salt as a natural resource, but almost no food grew there. The south had gold, but salt was scarce. So each region traded what it had for what it lacked: gold was an export of the south, and salt was an import. The environment decided what each place could produce and what it needed to buy."),
  mdc=dict(pregunta="Elías compared Mansa Musa's gold to a trading card that everybody has. Use this idea to explain why something becomes worth less when there is much more of it. Can you think of a modern example?",
    pregunta_es="Elías comparó el oro de Mansa Musa con una tarjeta que todos tienen. Usa esta idea para explicar por qué algo vale menos cuando hay mucho más. ¿Se te ocurre un ejemplo de hoy?",
    pista="When something is scarce, many people want it and it is worth a lot. When there is suddenly much more of it, fewer people need to pay a high price, so its value goes down. Modern examples: a toy that is rare at first and then sold everywhere, or strawberries that are cheaper in summer when there are many of them."),
  pausa=dict(emoji="🗺️", arte="Visual arts · VA:Cn11.1.6",
    intro="Look at a page of the Catalan Atlas, a map made in 1375 on the island of Majorca, which is now part of Spain, by a mapmaker named Abraham Cresques. Find Mansa Musa on it.",
    intro_es="Observa una página del Atlas Catalán, un mapa hecho en 1375 en la isla de Mallorca, que hoy forma parte de España, por un cartógrafo llamado Abraham Cresques. Busca a Mansa Musa en él.",
    enlace=("https://caravans.library.northwestern.edu/works/26/","See the Catalan Atlas (Northwestern University, Caravans of Gold)"),
    describe="The map is decorated with gold and bright colors. In West Africa, Mansa Musa sits on a throne wearing a golden crown. In one hand, he holds a scepter, and in the other, a large golden ball. A traveler on a camel rides toward him.",
    describe_es="El mapa está decorado con oro y colores brillantes. En África occidental, Mansa Musa está sentado en un trono con una corona de oro. En una mano sostiene un cetro y en la otra una gran bola dorada. Un viajero en camello cabalga hacia él.",
    preguntas=[("Why do you think the mapmaker painted Mansa Musa holding a big golden ball?","¿Por qué crees que el cartógrafo pintó a Mansa Musa con una gran bola dorada?"),
               ("Mansa Musa traveled in 1324, and this map was made in 1375, far away in Majorca. What does that tell you about how news traveled along trade routes?","Mansa Musa viajó en 1324 y este mapa se hizo en 1375, muy lejos, en Mallorca. ¿Qué te dice eso sobre cómo viajaban las noticias por las rutas comerciales?")],
    pista="The golden ball shows that Mali was known for its gold and its wealth. The mapmaker wanted merchants to see where the gold came from. Fifty years after his journey, people in Majorca still knew about Mansa Musa, so news about Mali must have traveled with merchants along the trade routes. A map is also a primary source: it shows what people in 1375 knew and believed.")),
]
